mapper.sql:
FROM fit_course_reservation r
INNER JOIN fit_course_schedule s ON s.schedule_id = r.schedule_id AND s.del_flag = '0'
INNER JOIN fit_course c ON c.course_id = s.course_id AND c.del_flag = '0'
LEFT JOIN fit_store st ON st.store_id = r.store_id AND st.del_flag = '0'
LEFT JOIN fit_coach coach ON coach.coach_id = s.coach_id AND coach.del_flag = '0'
LEFT JOIN fit_member m ON m.member_id = r.member_id AND m.del_flag = '0'
LEFT JOIN fit_member_card mc ON mc.card_id = r.card_id AND mc.del_flag = '0'
LEFT JOIN fit_checkin_record cr ON cr.reservation_id = r.reservation_id AND cr.del_flag = '0'
WHERE r.del_flag = '0'
AND r.reservation_no LIKE CONCAT('%', #{bo.reservationNo}, '%')
AND s.schedule_no LIKE CONCAT('%', #{bo.scheduleNo}, '%')
AND r.store_id = #{bo.storeId}
AND r.member_id = #{bo.memberId}
AND r.schedule_id = #{bo.scheduleId}
AND s.course_id = #{bo.courseId}
AND s.coach_id = #{bo.coachId}
AND r.reservation_status = #{bo.reservationStatus}
AND r.reservation_source = #{bo.reservationSource}
AND r.reservation_type = #{bo.reservationType}
AND r.consume_mode = #{bo.consumeMode}

AND s.schedule_date >= #{bo.scheduleDateStart}
AND s.schedule_date <= #{bo.scheduleDateEnd}
AND r.reservation_time >= #{bo.reservationTimeStart}
AND r.reservation_time <= #{bo.reservationTimeEnd}

    AND (m.real_name LIKE CONCAT('%', #{bo.keyword}, '%')
        OR m.mobile LIKE CONCAT('%', #{bo.keyword}, '%')
        OR c.course_name LIKE CONCAT('%', #{bo.keyword}, '%'))
